insert into public.academy_course_structures
    (app_slug, tier, structure, content_version)
insert into public.academy_quiz_questions
    (app_slug, tier, scope, module_key, ord, prompt, options, answer_index, explanation)
values
  ('esp', 'advanced', 'module', 'm01-from-head-to-horsepower', 1, 'Hydraulic power in this module is formed from which three quantities and one constant?', '["Rate times head times efficiency, divided by 58824.", "Rate times pressure times viscosity, divided by 3960.", "Rate times head times specific gravity, divided by HP_HEAD_DIVISOR, 135635.80083124.", "Rate times head times stage count, divided by 5252."]'::jsonb, 2, 'Neither the hydraulic step nor the brake step mentions a motor or a cable, so both belong entirely to the pump.'),
  ('esp', 'advanced', 'module', 'm01-from-head-to-horsepower', 2, 'What single quantity stands between a head requirement and the brake horsepower it costs?', '["The efficiency read off the stage curve at the duty rate.", "The motor efficiency printed on the nameplate, which converts the electrical input at the plate into work actually delivered at the shaft.", "The specific gravity of the produced fluid.", "The number of stages in the stack."]'::jsonb, 0, 'Brake power computed at an efficiency of zero comes back as NaN, so the engine will not invent one for you.'),
  ('esp', 'advanced', 'module', 'm01-from-head-to-horsepower', 3, 'Reading the published vendor curve at 2500 bbl/d on a 0.90 specific gravity fluid rather than a 1.00 one, which readings actually move?', '["Head and brake power both move, because a lighter fluid is lifted more easily and the stage therefore develops a taller column of it.", "Efficiency and brake power both move, because the hydraulic losses inside the stage scale with the density of the fluid being pumped.", "No reading moves, gravity being absent from this step.", "Brake power per stage alone, falling from 0.69851755 hp to 0.62866580 hp."]'::jsonb, 3, 'Head stays at 27.914286 ft and efficiency at 0.73657143, because density is a load term and does not touch the hydraulic shape.'),
  ('esp', 'advanced', 'module', 'm01-from-head-to-horsepower', 4, 'A stage curve fitted from points that carry no efficiency values at all comes back as what?', '["ok false, because a stage curve cannot be fitted without efficiency points, and no head fit is handed back to the caller either.", "ok true with a warning, head still readable, and both the best efficiency rate and brake power NaN.", "ok true with no warning at all, the missing efficiency being silently replaced by the value carried on the nearest catalogue stage.", "ok true with a warning, and brake power supplied from a default efficiency of 0.70 so that the power half of the curve keeps answering."]'::jsonb, 1, 'Two points is the input that does return ok false, the fit saying a stage curve needs at least three points from the vendor curve.'),
  ('esp', 'advanced', 'module', 'm01-from-head-to-horsepower', 5, 'Sizing a motor on the 87.10569922 hp recorded for the published gassyOffshore design leaves that motor short by what?', '["By the whole efficiency term, the brake duty being 125.69771587 hp.", "By the cable loss and the motor efficiency together, neither of which the hydraulic figure carries and both of which the brake figure does.", "By the rounding margin that the integer stage count buys.", "By nothing at all, the two being one duty."]'::jsonb, 0, 'The same trap sits on the teaching well IBENO-2 at 21.41688298 hp against 29.77428389 hp, and nothing downstream notices, because every later step takes the number it is handed.'),
  ('esp', 'advanced', 'module', 'm01-from-head-to-horsepower', 6, 'Why does one duty on one stack return two brake horsepowers with different values?', '["Because one figure is taken at the pump intake and the other at the discharge, the two differing by the head the stack develops across itself.", "Because one figure carries the specific gravity of the produced mixture while the other is quoted on a 1.00 gravity basis for comparison.", "Because the stage count rounds up, so the stack makes more head than it was asked for.", "Because the two are read at different drive frequencies."]'::jsonb, 2, 'The published gassyOffshore design needs 191.92829740 stages and gets 192, and both powers are correct arithmetic answering different questions.'),
  ('esp', 'advanced', 'module', 'm01-from-head-to-horsepower', 7, 'What margin does the published gassyOffshore stack carry over the head it was asked to make?', '["None, the stack making exactly the head required.", "1.85986141 ft, the stack making 4980.20162863 ft against a requirement of 4978.341767 ft.", "0.07170260 ft, worth one whole stage of head.", "4.65001300 ft, being the cable loss expressed as head."]'::jsonb, 1, 'That margin is 0.037359 percent, and the slack rounded away amounts to 0.07170260 of a stage.'),
  ('esp', 'advanced', 'module', 'm01-from-head-to-horsepower', 8, 'What fixes the gap between the two brake powers exactly, rather than leaving it a mystery?', '["The gap equals the brake power of a single stage, since exactly one stage of rounding is what separates the two figures on any stack.", "The gap equals the pump efficiency multiplied by the fraction of a stage that was rounded away when the count was formed.", "The gap is fixed by the specific gravity, which enters the stack figure and stays out of the shaft figure altogether.", "The ratio of the two powers equals the ratio of the two heads."]'::jsonb, 3, 'On the published gassyOffshore design both ratios read 1.000373590543 and their difference comes to -0.0000000000000004.'),
  ('esp', 'advanced', 'module', 'm01-from-head-to-horsepower', 9, 'The teaching well IBENO-2 loses 2.567658 percent to the rounding while the published gassyOffshore design loses 0.037359 percent. What accounts for that?', '["The slack is bounded by one stage, so a short stack spends it against far less head.", "The two designs round their stage counts by different rules, the shorter stack going to the nearest whole stage while the taller one always rounds upward.", "IBENO-2 runs at a lower drive frequency.", "IBENO-2 carries the heavier fluid of the two."]'::jsonb, 0, 'IBENO-2 is a 33 stage stack carrying 0.82611546 of a stage of slack, against 192 stages carrying 0.07170260.'),
  ('esp', 'advanced', 'module', 'm01-from-head-to-horsepower', 10, 'Sweeping the teaching well IBENO-2 requirement from 720 ft to 725 ft does what to its margin?', '["It falls smoothly from 2.580418 percent to 0.162698 percent, the requirement rising while the head made by a fixed stack stays exactly where it was.", "It holds flat, the margin being a fixed percentage of the head required and therefore blind to wherever the stage count happens to fall.", "It jumps from 0.162698 percent to 2.580418 percent as the count steps from 32 stages to 33.", "It doubles, the count stepping from 32 to 33."]'::jsonb, 2, 'The head made goes from 721.171425 ft to 743.708032 ft across those five feet of requirement, which is the sawtooth in one step.'),
  ('esp', 'advanced', 'module', 'm01-from-head-to-horsepower', 11, 'Which horsepower does the published motor sizing rule set out in PetroWiki take?', '["The brake power at the head required, 125.69771587 hp.", "Total stages times brake power per stage times specific gravity, which on the published gassyOffshore design is 192 stages at 0.6549201841 hp and lands on 125.74467535 hp.", "The hydraulic power, 87.10569922 hp.", "Whichever of the shaft power and the plate rating is larger."]'::jsonb, 1, 'Everything electrical in this package starts from the other figure, so the load fraction, the amps, the drop and the cable pick all inherit the smaller one.'),
  ('esp', 'advanced', 'module', 'm01-from-head-to-horsepower', 12, 'Building the amps on the smaller of the two brake powers moves an ESP design in which direction?', '["The non conservative one, the motor sitting closer to its plate than the published rule intends.", "The conservative one, since a lower assumed duty leaves headroom on the plate and forces a larger conductor to be picked downstream.", "Neither, the two agreeing to three figures.", "It moves the head required rather than the amps."]'::jsonb, 0, 'The amps come out lower than the published rule would give, and the voltage drop and the conductor choice inherit that understatement in full.'),
  ('esp', 'advanced', 'module', 'm01-from-head-to-horsepower', 13, 'The disagreement over which brake power should size the motor was recorded rather than corrected. Why?', '["The disagreement was found to sit inside the tolerance the goldens are compared at, so no edit could have been demonstrated by the test suite at all.", "The published sizing rule was judged out of date, so the package''s own choice was adopted as the house convention and written into the docstring instead.", "Both figures were found to be wrong.", "Every number in this engine is consumed by a live application, so a numeric edit moves a value somebody is reading today."]'::jsonb, 3, 'A convention can simply be quoted, while an open decision has to be stated as one, with the side the code sits on and the size of the disagreement given beside it.'),
  ('esp', 'advanced', 'module', 'm01-from-head-to-horsepower', 14, 'Running the cable selection for the teaching well IBENO-2 on a 3300 ft string at 140 degF, once on each brake power, produces what?', '["6 AWG on both runs, the two drops differing only in the fourth decimal place of a percentage.", "4 AWG on both runs, since the first conductor in the table fails the limit on either horsepower.", "6 AWG on the shaft figure and 4 AWG on the stack figure.", "No cable on either run, every candidate in the shipped table exceeding the 5.0 percent limit."]'::jsonb, 2, 'The 6 AWG drop reads 4.938649 percent on one power and 5.065457 percent on the other, and the limit of 5.0 percent sits between them.'),
  ('esp', 'advanced', 'module', 'm01-from-head-to-horsepower', 15, 'Four demonstration cases keep the same conductor on both powers while one does not. What does that exception require?', '["The two horsepowers have to differ by more than one whole stage of head.", "The winning drop has to land between the limit divided by the power ratio and the limit itself, a window only the rounding margin wide.", "The cable string has to be long enough for the drop to exceed the limit.", "The motor plate has to be smaller than the shaft power asks of it."]'::jsonb, 1, 'That window is wide only where the ratio is, so a 33 stage design at 1.025676584275 moved while a 192 stage design at 1.000373590543 could not.'),
  ('esp', 'advanced', 'module', 'm02-the-motor', 1, 'The shipped catalogue lists a 150 hp motor drawing 48 A and a 100 hp motor drawing 49 A. What explains that?', '["The larger motor is quoted at part load while the smaller one is quoted at its full load rating, so the two currents are not comparable.", "Voltage is doing the work, 2000 V against 1300 V.", "The larger motor runs at a better efficiency.", "The two are rated at different frequencies."]'::jsonb, 1, 'These are published catalogue entries rather than computed results, and the 400 hp motor draws 78 A because it sits on 3300 V.'),
  ('esp', 'advanced', 'module', 'm02-the-motor', 2, 'What does the published motor selection rule do with the thrust derating factor?', '["It multiplies the nameplate current by the factor before the amps are formed.", "It subtracts the factor from the load fraction already in hand.", "It applies the factor to the head required, before any horsepower is formed.", "It divides the required horsepower by that factor, which measures utilisation against the usable rating rather than against the plate."]'::jsonb, 3, 'The factor is one minus the derate, so 0.9200 at 8 percent and 0.8000 at 20 percent, and not one of the three plate numbers moves.'),
  ('esp', 'advanced', 'module', 'm02-the-motor', 3, 'The published gassyOffshore design reports 0.5027908635 at no derate and 0.6284885794 at a 20 percent derate. What changed between those two figures?', '["Only the allowance, the shaft still asking for 125.69771587 hp.", "The duty rose, the derate placing an extra thrust load on the shaft that the pump must now supply out of the same stack of stages.", "The motor was exchanged for a smaller frame, so the same shaft power is being measured against a lower nameplate horsepower.", "The pump efficiency fell at the duty rate."]'::jsonb, 0, 'A design reporting the larger of those figures has not become busier, and carrying that figure into an amps calculation would overstate the current.'),
  ('esp', 'advanced', 'module', 'm02-the-motor', 4, 'On a 250 hp, 67 A plate an electrical load fraction of 0.5000000000 asserts what?', '["That the motor is running at half of its rated efficiency, the remainder leaving the machine as heat into the annulus.", "That the motor has half of its thrust allowance still in hand, once the derate on the running condition has taken its share.", "33.500000 A, and nothing beyond that.", "That the motor will survive twice as long as one loaded to its plate, the current being linear in loading."]'::jsonb, 2, 'The motor efficiency of 0.85 and the power factor are separate inputs, and neither enters the step that scales the plate current.'),
  ('esp', 'advanced', 'module', 'm02-the-motor', 5, 'Which thresholds watch a load fraction, and where does each of them sit?', '["motorOverloaded above 1.1 and motorUnderloaded below 0.4, with no flag on the current.", "motorOverloaded above a selection fraction of 1, motorUnderloaded below 0.5, and the current estimate flagged weak below 0.5.", "A single band running from 0.5 to 1, outside which sizing refuses to return.", "motorOverloaded above 1 only, the low end being unwatched."]'::jsonb, 1, 'Sizing raises the first two of those and the current module raises the third, and neither module knows that the other exists.'),
  ('esp', 'advanced', 'module', 'm02-the-motor', 6, 'The teaching well IBENO-2 raises motorUnderloaded at no derate and raises nothing at a 5 percent derate. What moved?', '["Only the derate, the selection fraction going from 0.4962380648 to 0.5223558577.", "The duty moved, the pump having been resized onto a shorter stack whose shaft power now sits above the underloaded threshold.", "The motor was changed for a smaller plate.", "The drive frequency was raised."]'::jsonb, 0, 'Neither the motor nor the pump changed, so a threshold reports which side of a line a number fell on and nothing about how far it fell.'),
  ('esp', 'advanced', 'module', 'm02-the-motor', 7, 'At a fifth of plate the engine returns 0.2000 and 9.8000 A with the estimate flagged weak. Why is that flag there?', '["Below about half load the nameplate current itself becomes an unreliable figure, since a manufacturer measures it only at the full load operating point.", "Below about half load the power factor collapses, so the apparent power at the surface can no longer be recovered from the real power at the shaft.", "Because a fraction that small implies a plate of zero.", "Below about half load the real current flattens toward the magnetising current while a linear scaling keeps falling toward zero."]'::jsonb, 3, 'The 9.8000 A comes back unchanged, still linear and still wrong in the direction the flag describes, because the flag is the whole of the response.'),
  ('esp', 'advanced', 'module', 'm02-the-motor', 8, 'Where does the motor efficiency of 0.85 enter the published gassyOffshore design?', '["In the load fraction, which is the shaft power divided by the plate power once that efficiency has been applied to it.", "In the pump efficiency of 0.6929775821, which already carries the motor loss at the duty rate the stage is read at.", "Separately, in reaching 110.273867 kW of motor input power.", "In the resistive voltage drop down the cable, alongside the power factor that shares the same surface calculation."]'::jsonb, 2, 'A load fraction is not an efficiency, not a power factor, not a temperature and not a statement about how long a loading is survivable.'),
  ('esp', 'advanced', 'module', 'm02-the-motor', 9, 'How do sizePump and motorCurrent differ in the fraction each of them forms?', '["sizePump divides by the plate power times the derating factor, while motorCurrent divides by the plate power alone.", "sizePump divides by the plate power alone, while motorCurrent applies the derating factor so that the amps reflect the thrust allowance in the running condition.", "Both apply the derating factor, at different points.", "Neither applies it, the derate being advisory."]'::jsonb, 0, 'On the published gassyOffshore design the electrical figure stays at 0.5027908635 at every derate, so a design that changes only its thrust condition produces an identical electrical result.'),
  ('esp', 'advanced', 'module', 'm02-the-motor', 10, 'What is the physical argument for keeping the thrust derate out of the motor current?', '["The derate belongs to the cable, not to the motor.", "Motor current is nearly linear with horsepower loading, and cutting a permissible load does not change the work the shaft is doing.", "The derate is applied later, at the surface.", "Current is set by the plate voltage and cannot move."]'::jsonb, 1, 'Were the derate to reach the current, the amps would rise while the mechanical duty stood still, and no meter in the field would read that.'),
  ('esp', 'advanced', 'module', 'm02-the-motor', 11, 'What is the closed form of the gap between the two fractions?', '["The difference between the plate horsepower and the shaft horsepower, divided by the derating factor and then expressed as points.", "The derate itself expressed in points, which is why a 20 percent derate opens a gap of exactly twenty points on any design at all.", "The electrical load fraction times the quantity one over the derating factor less one.", "One half of the derate, in points."]'::jsonb, 2, 'Evaluated at a load fraction of 0.89714 with a 12 percent derate it comes to 12.2337 points, and it is zero only where the derate is zero.'),
  ('esp', 'advanced', 'module', 'm02-the-motor', 12, 'The teaching well QUA-IBOE-4 at a 5 percent derate is reported overloaded by one module and not overloaded by the other. How is that possible?', '["The two modules are reading the well at different derates, sizing having been run before the thrust condition was applied and the current module after it.", "One module rounds the fraction and the other does not.", "The warning is raised on plate current rather than on power.", "Its selection fraction crosses one at 1.0043811889 while the electrical fraction stays at 0.9541621294."]'::jsonb, 3, 'The published highWaterCut design crosses the same way later, at a 15 percent derate, against an electrical fraction fixed at 0.8627982600.'),
  ('esp', 'advanced', 'module', 'm02-the-motor', 13, 'What does substituting the sizing figure for the electrical one on the teaching well QUA-IBOE-4 at a 20 percent derate cost?', '["23.854053 points of overstatement, carried into the current, the voltage drop and the cable selection at once.", "Nothing, the two agreeing at that derate.", "A single warning, raised by the current module.", "5.021906 points, the gap at the first derate that bites."]'::jsonb, 0, 'The design report and the electrical report would then disagree while each stayed internally consistent, which is how such a substitution survives a review.'),
  ('esp', 'advanced', 'module', 'm02-the-motor', 14, 'Two complaints of one shape reached the same review, yet the two brake powers were recorded as an open decision while the two load fractions were called a naming defect. What separates them?', '["The powers differ by an amount large enough to move a cable size, while the fractions differ by too little on the cases examined to change any downstream number at all.", "The powers are produced inside one module while the fractions are produced by two, and a review may only record a finding that crosses a module boundary in that way.", "The powers are one quantity computed twice, so at most one may feed the chain, while the fractions are two quantities sharing a label.", "The powers were published and the fractions were not."]'::jsonb, 2, 'The first is a bug about arithmetic and the second a bug about vocabulary, and the second is repaired by naming rather than by changing any value.'),
  ('esp', 'advanced', 'module', 'm02-the-motor', 15, 'Which test tells a reader which of those two verdicts a disagreement deserves?', '["Ask whether the two figures differ by more than the tolerance the goldens are compared at, and record the finding only where they do.", "Ask whether it is one thing computed twice or two things wearing one label.", "Ask which of the two figures the published literature quotes, and treat the other of them as the defect wherever the two disagree.", "Ask whether the disagreement is visible in a saved design, since a value nobody has stored yet may be edited freely."]'::jsonb, 1, 'Both load fraction computations stand, each being arithmetically right for what it means, so the shared name is the entire defect.'),
  ('esp', 'advanced', 'module', 'm03-amps-and-cable', 1, 'How does the engine form the motor current?', '["The nameplate current times shaft power over nameplate power.", "The shaft power divided by the product of the nameplate voltage, the power factor and the square root of three, which is the usual three phase form.", "The nameplate current times the shaft power over the plate power, corrected by a motor efficiency read at the running load fraction.", "The apparent power divided by the plate voltage."]'::jsonb, 0, 'Across both golden electrical cases the largest relative deviation between the engine and the recorded golden is 0.00000000000064.'),
  ('esp', 'advanced', 'module', 'm03-amps-and-cable', 2, 'Why does no motor efficiency curve and no power factor curve enter that step?', '["Because a submersible motor runs at a constant efficiency and a constant power factor across its whole loading range, so no curve is needed for either.", "Because both are supplied as inputs to the drop.", "A nameplate already carries both at full load, so scaling it carries them along at the one point where they are known.", "Because both belong to the pump rather than the motor."]'::jsonb, 2, 'The consequence is a boundary at half load, below which the estimate is flagged weak because the scaling interpolates those two quantities nowhere.'),
  ('esp', 'advanced', 'module', 'm03-amps-and-cable', 3, 'What does hanging a different conductor on the teaching well QUA-IBOE-4 do to its 46.753944 A?', '["It falls as the conductor gets larger.", "Nothing, the current being set at the machine while the cable only spends voltage carrying it.", "It rises, a larger conductor drawing more.", "It moves once the drop exceeds the limit."]'::jsonb, 1, 'The plate behind that figure is the catalogue motor m-100-1300, and the fraction is 0.9541621294 with no thrust derate anywhere in it.'),
  ('esp', 'advanced', 'module', 'm03-amps-and-cable', 4, 'What are the four factors in the three phase voltage drop?', '["1.7320508076, the current, the resistance and the power factor, the last of these setting how much of the drop is resistive.", "The current, the resistance, the length in thousands of feet and the nameplate voltage the percentage is later taken against.", "The current, the reactance, the length in thousands of feet and a skin effect correction taken at the running frequency.", "1.7320508076, the current, the resistance and the length in thousands of feet."]'::jsonb, 3, 'Power factor stays out of this step entirely, belonging instead to the apparent power at the surface.'),
  ('esp', 'advanced', 'module', 'm03-amps-and-cable', 5, 'Reading 2 AWG at 250 degF rather than at 77 degF changes the resistance by what?', '["A factor of 1.22488333, the temperature coefficient being referenced to the surface ambient rather than to a laboratory condition.", "Nothing, the table already being at well temperature.", "A factor of 1.37771667, from 0.1593000000 to 0.2194702650 ohms per 1000 ft.", "A factor of 0.72, copper improving with heat."]'::jsonb, 2, 'The correction is a linear coefficient of 0.0021833333 per degF referenced to 77 degF, so a design quoting the shelf value at such a well understates the resistance by more than a third of itself.'),
  ('esp', 'advanced', 'module', 'm03-amps-and-cable', 6, 'Against which voltage is the drop percentage taken?', '["The motor nameplate voltage, so golden electrical case 1 divides 81.51704573 V by 2400 V.", "The surface voltage, so golden electrical case 1 divides 81.51704573 V by the 2481.51704573 V that the surface has to supply.", "The difference between the surface voltage and the nameplate voltage, which is what the conductor actually gives up along its length.", "The catalogue voltage of the largest motor."]'::jsonb, 0, 'The two denominators do not give the same answer, and taking the larger of them understates the drop, which is one of the two mistakes here that flatter a design.'),
  ('esp', 'advanced', 'module', 'm03-amps-and-cable', 7, 'Golden electrical case 1 has three conductors clearing the limit. Which one is selected, and why?', '["1/0 AWG at 2.136432 percent, being the lowest drop.", "2 AWG at 3.396544 percent, the scan running from the smallest conductor and stopping at the first candidate that passes.", "1 AWG at 2.695060 percent, being the middle pass.", "2 AWG, being the conductor nearest the limit."]'::jsonb, 1, 'The routine buys the smallest acceptable conductor rather than the best one, and golden electrical case 2 shows how little margin that leaves, being decided at 4.983392 percent.'),
  ('esp', 'advanced', 'module', 'm03-amps-and-cable', 8, 'What comes back when no candidate in the table clears the limit?', '["The largest conductor in the table, flagged as failing, so that a caller has something to price while the limit is being reconsidered.", "An error, the routine refusing to return.", "No cable at all, rather than the least bad candidate presented as an answer.", "The candidate with the smallest drop, unflagged."]'::jsonb, 2, 'The teaching well QUA-IBOE-4 does exactly that on the default limit, its 46.753944 A leaving even 1/0 AWG at 6.017615 percent.'),
  ('esp', 'advanced', 'module', 'm03-amps-and-cable', 9, 'Why does the ampacity check come back true on every candidate over the shipped table?', '["The shipped conductors are all rated well above the currents these designs draw, so the test is passed on its merits every time it is run.", "The test is evaluated only after the drop test has already failed, so a passing candidate never reaches that second test at all.", "Ampacity is derived from the resistance, and every conductor in the table carries a resistance low enough to clear the derived figure.", "A candidate that declares no ampacity passes the test, and none of the five declares one."]'::jsonb, 3, 'The two tests are combined with an AND, so over the shipped table that AND has exactly one live operand.'),
  ('esp', 'advanced', 'module', 'm03-amps-and-cable', 10, 'What does the published 192 A gate show about the pick over the shipped table?', '["That the acceptable flag collapses onto the drop flag alone, 6 AWG being taken at 192.000000 A because its 155.302473 V sits inside 5 percent of 4160 V.", "That the drop test and the ampacity test disagree on 6 AWG.", "That no candidate clears the limit on a 1000 ft string.", "That 1 AWG is taken, its ampacity being sufficient."]'::jsonb, 0, 'The string is short, so even the smallest conductor passes on drop, and the pick is therefore decided by one flag out of the two reported.'),
  ('esp', 'advanced', 'module', 'm03-amps-and-cable', 11, 'Supplying a manufacturer ampacity column to that same run changes what?', '["The arithmetic, a second term entering the drop calculation so that each candidate is now assessed on heating as well as on the volts it gives up.", "The data alone, 1 AWG at 220 being taken and the cable loss falling from 51.646421 kW to 16.206821 kW.", "Nothing at all, since the drop test had already passed on every candidate and a passing candidate cannot be rejected by any later test.", "The limit, which widens to admit 1 AWG."]'::jsonb, 1, '6 AWG declares 105, 4 AWG declares 140 and 2 AWG declares 190, so all three fail at 192.000000 A.'),
  ('esp', 'advanced', 'module', 'm03-amps-and-cable', 12, 'Which sentence states this finding honestly?', '["The cable that came back is undersized for the current.", "The drop test is unreliable and should be replaced.", "The ampacity half of the method did not run, which holds on the gate fixture, on the teaching wells and on every other case.", "The shipped table is wrong and needs correcting."]'::jsonb, 2, 'That is the difference between a useful report and a false alarm, one sentence describing a check that is missing while the other accuses a conductor that may be perfectly sound.'),
  ('esp', 'advanced', 'module', 'm03-amps-and-cable', 13, 'Why does the package decline to ship an ampacity column at all?', '["Ampacity belongs to the insulation system and the well temperature, so it is an input rather than a property of the copper.", "Ampacity varies with the drive frequency and with the harmonic content of the controller, neither of which is modelled here, so any shipped figure would be defensible at one operating point only.", "The published tables are held under copyright.", "Ampacity is already implied by the resistance."]'::jsonb, 0, 'The same refusal runs through the package, which likewise carries no manufacturer part numbers with invented curves behind them.'),
  ('esp', 'advanced', 'module', 'm03-amps-and-cable', 14, 'Which inputs can move a cable pick, and which cannot?', '["The shaft power, the plate, the thrust derate and the power factor move it, while the conductor temperature and the string length are absorbed into the resistance term beforehand.", "The shaft power, the plate, the conductor temperature and the length move it, while the thrust derate and the power factor do not.", "The limit and the ampacity move it, while the shaft power reaches the pick only through the load fraction and is therefore already accounted for.", "Only the limit and the string length move it."]'::jsonb, 1, 'Auditing a pick by re-reading the cable table is the least likely thing to be wrong, since three of the four live inputs sit in another module or in a default.'),
  ('esp', 'advanced', 'module', 'm03-amps-and-cable', 15, 'The teaching well IBENO-2 draws 18.857046 A and comes back with 6 AWG. What may fairly be said about that pick?', '["That it is unsafe, since the ampacity test which ought to have caught it passed without examining any figure at all.", "That it cannot be judged, the drop percentage having been formed on the wrong horsepower in the first place.", "That it should be rejected until the missing ampacity column is supplied and the whole selection is run again.", "That no ampacity table would object to it, so calling it unsafe would be false."]'::jsonb, 3, 'What is true of every such pick is that the ampacity half of the method took no part, which is a statement about the report rather than about the conductor.'),
  ('esp', 'advanced', 'module', 'm04-at-the-surface', 1, 'What does surfaceVolts contain?', '["The motor nameplate voltage plus the three phase resistive drop down the cable, and nothing whatever else.", "The nameplate voltage plus the drop, scaled by the power factor.", "The switchboard voltage less the drop down the string.", "The nameplate voltage plus the drop and a transformer tap."]'::jsonb, 0, 'The drop inside it is 1.7320508076 times the current, times the conductor resistance at the cable temperature, times the length in thousands of feet.'),
  ('esp', 'advanced', 'module', 'm04-at-the-surface', 2, 'Golden electrical case 2 comes back at 1506.44804157 V on a drop of 15.88061858 percent. What does that show?', '["That the plate voltage was entered wrongly.", "That a 1300 V motor cannot be run down 6000 ft.", "That surfaceVolts only reports, while dropPct is the field that judges.", "That the routine has already rejected the conductor and returns the voltage for information only, the selection having moved on to the next candidate in the shipped table."]'::jsonb, 2, 'The default selection limit is 5 percent, so the voltage is computed in full precision for a cable no method would accept.'),
  ('esp', 'advanced', 'module', 'm04-at-the-surface', 3, 'Why is the current identical at every row of the 2 AWG temperature table while the voltage at surface is not?', '["The switchboard regulator holds the current steady by raising its voltage as the conductor warms, so that the motor keeps seeing its plate whatever the well does.", "The current is set at the machine, and only the conductor resistance moved with the temperature.", "The current was formed at the 77 degF reference and the engine declines to recompute it once a cable temperature has been supplied by the caller.", "The table was drawn at a fixed current."]'::jsonb, 1, 'Copper is corrected from 77 degF at 0.0021833333 per degF, so the same conductor reads 0.1593000000 ohms per 1000 ft cold and 0.2194702650 at 250 degF.'),
  ('esp', 'advanced', 'module', 'm04-at-the-surface', 4, 'Which of these has the surface requirement no model of at all?', '["The conductor resistance at the cable temperature, which has to reach the call as an ohms per 1000 ft figure supplied by the caller.", "The factor 1.7320508076, which enters the conductor loss and takes no part in the drop itself.", "The motor nameplate voltage, the switchboard being what defines the voltage a design is built around.", "Transformer taps, reactance, starting current and voltage unbalance."]'::jsonb, 3, 'It also never checks that the motor sees its plate, because the current it used came from scaling that plate by the load fraction in the first place.'),
  ('esp', 'advanced', 'module', 'm04-at-the-surface', 5, 'How is the kVA at surface formed?', '["Root three times surfaceVolts times the motor current, divided by 1000.", "Root three times the motor nameplate voltage times the current over 1000, the cable drop being accounted for separately in the loss field.", "The kW divided by the power factor of 0.85.", "The shaft power converted to kW and divided by the power factor."]'::jsonb, 0, 'It therefore rests on the voltage at the top of the cable, which already contains the drop, and on the current the motor draws.'),
  ('esp', 'advanced', 'module', 'm04-at-the-surface', 6, 'Case 2 draws 38.220000 A against 33.500000 A and still returns the lower apparent power. What explains it?', '["Its cable is 6000 ft against 7200 ft, and a shorter string returns less apparent power to the switchboard.", "Its power factor of 0.88 against 0.85 pulls the apparent power down, the two being one multiplication apart.", "Its motor plate is 1300 V against 2400 V, so voltage carries the kVA.", "Its shaft power of 78.00 hp is the smaller of the two."]'::jsonb, 2, 'The figures are 99.72532659 kVA against 143.98680570 kVA, so current alone settles nothing here.'),
  ('esp', 'advanced', 'module', 'm04-at-the-surface', 7, 'Where does the power factor enter the surface numbers?', '["In the drop and in the kVA alike.", "Only in the step from kVA to kW, and it is a caller input with no curve of any kind behind it.", "In the kVA, which is apparent power.", "In the loss, the current heating the copper in phase."]'::jsonb, 1, 'It defaults to 0.85, which is the value on golden electrical case 1, while case 2 was run at 0.88.'),
  ('esp', 'advanced', 'module', 'm04-at-the-surface', 8, 'A designer multiplies the voltage drop by the power factor on the way down the hole. What follows?', '["A warning, because the drop routine checks that any power factor handed to it took no part in the resistive calculation before it returns.", "Nothing at all, the power factor cancelling again when the apparent power is formed from the very surface voltage that the drop produced.", "A larger conductor loss to compensate, the same power having to reach the motor however the drop is apportioned between the two fields.", "A smaller drop, a smaller surface voltage, a smaller kVA and, on a table of candidates, a different cable."]'::jsonb, 3, 'Nothing in the returned object flags it, because the function was handed the answer it was asked for.'),
  ('esp', 'advanced', 'module', 'm04-at-the-surface', 9, 'How is lossKw formed?', '["Three times the current squared, times the resistance, times the length in thousands of feet, over 1000.", "Root three times the current squared, times the resistance at the 77 degF reference, times the length in thousands of feet, over 1000.", "The apparent power less the real power.", "The drop times the current, divided by 1000."]'::jsonb, 0, 'It uses the same corrected resistance the voltage drop uses, so both figures move together with the well temperature.'),
  ('esp', 'advanced', 'module', 'm04-at-the-surface', 10, 'Golden electrical case 2 leaves 13.66665016 kW in a 6000 ft string where case 1 leaves 4.72992077 kW in 7200 ft. What accounts for that?', '["The longer string on the first spreads its heat over more copper, so identical watts per foot report as a smaller total.", "The power factor of 0.85 on the first keeps more of the current out of phase and therefore out of the conductor heating.", "A higher current on a conductor reading 0.5197664067 ohms per 1000 ft against 0.1951239150.", "The lower plate voltage on the second."]'::jsonb, 2, 'As a share of real power those are 15.573059 percent against 3.864668 percent, so the shorter cable is by far the worse installation.'),
  ('esp', 'advanced', 'module', 'm04-at-the-surface', 11, 'Why do the drop check and the conductor heat not raise their concerns at the same moment?', '["The heat is computed at the 77 degF reference while the drop is corrected to the well.", "Loss goes as the square of the current while the drop goes as the current itself, so a published gate passes 192.000000 A at 3.733233 percent of drop and still leaves 51.646421 kW in the copper.", "The heat is judged against a separate and looser limit.", "The drop is taken on the plate voltage and the heat on the surface voltage, and those differ."]'::jsonb, 1, 'The number that would have refused that pick is not the number being checked, since selection runs on the drop percentage alone.'),
  ('esp', 'advanced', 'module', 'm04-at-the-surface', 12, 'What is the circle this module never closes?', '["The loss is taken off the kW to give motor input power, and that figure is never compared against the shaft power it ought to match.", "The current behind the heat came from scaling a plate, and it is never checked against what a surface meter would read on the same installation.", "The resistance behind the heat is the catalogue figure at 77 degF, and the corrected value never reaches the field that reports the watts.", "The watts it returns would set the very cable temperature it was handed, and nothing feeds them back."]'::jsonb, 3, 'A colder assumed temperature gives a lower resistance, a lower loss and a lower drop, so the result is self consistent and wrong in the direction that flatters a design.'),
  ('esp', 'advanced', 'module', 'm04-at-the-surface', 13, 'Which of the four returned fields is a conductor actually selected on?', '["The drop percentage, against a default limit of 5 percent.", "The cable loss, the conductor being chosen so its dissipated heat stays inside the rating of the insulation system.", "The apparent power, since equipment is bought in it.", "The voltage the switchboard has to present."]'::jsonb, 0, 'Each of the four is complete on its own and each is used by a different person, which is why they were never built to combine.'),
  ('esp', 'advanced', 'module', 'm04-at-the-surface', 14, 'Why is cable heat quoted as a percentage of the real power rather than taken off it?', '["A subtraction would need both in one unit, and the heat comes back in kW while the apparent power comes back in kVA.", "A percentage compares two returned fields, while a subtraction would be a claim about where the power went.", "A percentage is what a switchboard supplier asks for, an absolute figure being useful only once a conductor temperature rise has been established.", "Percentages compare more readily between wells."]'::jsonb, 1, 'Neither adding the heat to the real power nor taking it away produces anything a surface meter reads, and energy must never be billed off the kW field.'),
  ('esp', 'advanced', 'module', 'm04-at-the-surface', 15, 'Where does the 110.273867 kW of motor input power on golden design gassyOffshore come from?', '["From the real power less the conductor heat.", "From the apparent power times the power factor.", "From 125.69771587 hp of shaft at a stated motor efficiency of 0.85, an assumption held outside the electrical call.", "From the surface voltage and the current at root three."]'::jsonb, 2, 'No efficiency curve exists anywhere in this module, so none of the apparent power, the real power or the heat equals that figure or can be made to.'),
  ('esp', 'advanced', 'module', 'm05-diagnosis', 1, 'What does a diagnosis do that a design does not?', '["It fits a fresh curve to the measured points and compares that fit against the published one.", "It reads the same stage curve backwards, working out what a running stack should make at the measured rate and speed and dividing.", "It names the failure mode behind a shortfall in head, choosing among wear, free gas through the stages and a stack that was built with too few stages.", "It recomputes the stage count from the measured head and reports how many stages of the original stack are no longer doing any useful work."]'::jsonb, 1, 'Every field it returns is a reading or a ratio, and not one of them is a cause.'),
  ('esp', 'advanced', 'module', 'm05-diagnosis', 2, 'The published gate fixture runs 200 stages of reference stage ref-540-2500 at 2500 bbl/d and 60 Hz. What does it expect?', '["28.00000000 ft per stage, 5600.000000 ft from the stack, an efficiency of 0.7000000000 and 140.08101020 hp absorbed.", "5600.000000 ft from the stack at an efficiency of 0.95, that figure being the specific gravity of the fluid.", "28.00000000 ft per stage and a region of upthrust.", "5000.00000000 ft from the stack, at a region of recommended."]'::jsonb, 0, 'The specific gravity behind the brake power there is 0.95, and the region comes back as recommended.'),
  ('esp', 'advanced', 'module', 'm05-diagnosis', 3, 'By which second route can measured head reach the comparison?', '["Rebuilt from the drive frequency and the affinity laws applied to the published curve, which needs no pressure measurement at all.", "Taken from the motor amps, since current is nearly linear with the loading the head represents on the shaft.", "Derived from the stage count and the best efficiency rate, both of which the surveillance record already carries.", "Recovered from an intake and a discharge pressure, through a gradient of 0.433 times the specific gravity."]'::jsonb, 3, 'On the fixture that gradient is 0.41135000 psi/ft, and 800 psia against 2856.750000 psia recovers 5000.00000000 ft for a ratio of 0.8928571429.'),
  ('esp', 'advanced', 'module', 'm05-diagnosis', 4, 'What is the risk in the rounded 0.433 that the pressure recovery uses?', '["The recovered head is always too small, the rounding being downward.", "The recovery refuses to run when a specific gravity above one is supplied.", "The head comes back on a different gradient from the one the design was built on.", "The gradient constant is exposed as an input, so two readings of one well can be taken on two different values of it."]'::jsonb, 2, 'It stands 0.076982 percent from the exact 0.433333333333 that the density conversion carries.'),
  ('esp', 'advanced', 'module', 'm05-diagnosis', 5, 'Where do the two region boundaries sit?', '["At the head ratios of 0.85 and 1.15, the region reading being the same comparison the head flags are judged on under another name.", "At 0.75 and 1.25 of the best efficiency rate, so 0.750375 reads recommended while 1.250225 does not.", "At 0.50 and 1.50 of the best efficiency rate, which is the band a vendor prints across the published curve sheet.", "Wherever the fitted curve turns over, which the fit reports."]'::jsonb, 1, 'A region is a statement about where the duty landed on the curve, not about the condition of the pump.'),
  ('esp', 'advanced', 'module', 'm05-diagnosis', 6, 'Which of the four bands puts no ratio in its message, and why?', '["The one for excess head, since more head than the curve allows is evidence that an input is wrong rather than a degree of anything.", "The low amps band, a lightly loaded motor giving no reliable figure to print.", "The high amps band, a nameplate current being absent on many records.", "The low head band, its three causes being indistinguishable."]'::jsonb, 0, 'Its message lists the rate, the pressures, the fluid gradient and the stage count instead, which is the whole list of inputs that could produce it.'),
  ('esp', 'advanced', 'module', 'm05-diagnosis', 7, 'A stack makes 4760.000000 ft where its curve expects 5600.000000 ft. What is raised?', '["The low head flag, since the shortfall is more than a tenth.", "The low head flag together with a downthrust region.", "Nothing at all, that being a ratio of 0.8500 and the band opening below it.", "Nothing, because the region reading has priority over the head reading and the duty was inside the recommended band."]'::jsonb, 2, 'One further foot of shortfall reaches 0.8499 and does raise it, so those two readings differ in their fourth digit.'),
  ('esp', 'advanced', 'module', 'm05-diagnosis', 8, 'The amps ratio is set to exactly 1.0500 and then to exactly 0.4000. What comes back?', '["Both flags, thresholds being inclusive on the side they were written for.", "The high flag at 1.0500 and no flag at 0.4000, the upper band alone being inclusive.", "No flag at 1.0500 and the low flag at 0.4000, which is 24.0000 A on the fixture nameplate.", "No flag either time, every band being a strict inequality."]'::jsonb, 3, 'At 0.3999, which is 23.9940 A, the low flag does fire, so a boundary value always sits on the quiet side of its band.'),
  ('esp', 'advanced', 'module', 'm05-diagnosis', 9, 'What was the shape of the defect the review fixed?', '["Three flags fired on the wrong side of their thresholds.", "Three messages formatted their ratio with no decimal places, so each printed the threshold it had just failed.", "Three thresholds were compared with the wrong inequality.", "Three messages named a cause the function has no model for."]'::jsonb, 1, 'The flag was right and the ratio was right, and only the sentence a human read contradicted itself.'),
  ('esp', 'advanced', 'module', 'm05-diagnosis', 10, 'At an amps ratio of 1.0550 the old whole percent format printed 106. What does that establish?', '["That the rounding erred upward as readily as downward, the true figure there being 105.5.", "That the high amps band had been written against the wrong threshold.", "That the collision runs from 1.05 all the way to 1.06.", "That the printed figure was formed on the current rather than on the ratio, 63.3000 A rounding up to a whole ampere."]'::jsonb, 0, 'Below that value the same format printed 105, so the band beside the threshold was where a reader was misled.'),
  ('esp', 'advanced', 'module', 'm05-diagnosis', 11, 'What does the one decimal place fail to remove?', '["The three flags themselves, which continue to fire on exactly the thresholds they carried before, at every ratio a record can present.", "The gap between the two gradient conversions.", "The collision itself, since 0.8495 and 0.8499 still print 85.0 percent under a flag that cannot fire at 85.", "The rounding of the amps ratio, which was left on whole percentages because the current it comes from is itself only read to a whole ampere."]'::jsonb, 2, 'The band that can still print its threshold is a tenth of what it was, running from 0.8495 rather than from 0.845, so any fixed precision keeps a last digit and keeps a band with it.'),
  ('esp', 'advanced', 'module', 'm05-diagnosis', 12, 'How does the new gate show that a test on a message is testing something?', '["It compares each whole message against a stored string, so any wording change anywhere in the function turns the suite red.", "Reverting each format in turn turns exactly that one boundary band red and leaves the other two green.", "It pins the three thresholds and asserts that no returned field moved, which is the audit the change was allowed on.", "It runs the fixture at every ratio between 0.3900 and 1.2000 and counts the flags raised."]'::jsonb, 1, 'The gate pins all three boundary bands and asserts that the printed number is not the threshold.'),
  ('esp', 'advanced', 'module', 'm05-diagnosis', 13, 'What are the three counts that describe the change?', '["One threshold moved, no returned field moved, and three message templates were rewritten to carry the new value.", "No threshold moved, three returned fields gained a decimal place, and no message template was touched at all.", "Three thresholds moved by half a tenth each, no returned field moved, and one message template was rewritten.", "No threshold moved, no returned field moved, and three message templates were rewritten."]'::jsonb, 3, 'Every flag that fired before the change fires after it at the same ratio, and every returned number is bit for bit what it was.'),
  ('esp', 'advanced', 'module', 'm05-diagnosis', 14, 'Of the five findings this wave examined, why was this the one that could be changed?', '["It moved a printed string, while each of the other four would move a number a live application is showing somebody today.", "It was the only one confirmed as a genuine defect.", "It was the cheapest of the five to implement.", "It was the only one with a gate already written for it."]'::jsonb, 0, 'A returned field is consumed by a design, a spreadsheet and a report, while a message is read once by a person and consumed by nobody.'),
  ('esp', 'advanced', 'module', 'm05-diagnosis', 15, 'Why does the low head flag decline to choose among its own causes?', '["The record rarely carries enough of a history to separate them.", "The three are separated by the region reading instead.", "Wear, free gas through the stages and a wrong stage count all lower the head made without touching the curve compared against.", "The three would each need a wear model, a gas lock model and a rebuild of the stack, none of which the surveillance record is allowed to trigger."]'::jsonb, 2, 'A specific gravity error in the pressure recovery lands in the same place, which is why a bad input cannot be told from a bad pump here.'),
  ('esp', 'advanced', 'module', 'm06-the-expert-reading', 1, 'The motor, the cable, the stage count, the derate and the power factor belong on which of the tier''s three lists?', '["The conventions, being defensible choices that are not unique.", "The artefacts, since each is an accident of how two modules were joined and each would be absent from a package assembled today.", "The readings, since every one of them comes back from the engine as a computed figure rather than reaching it as an input.", "The decisions, each of which somebody signs."]'::jsonb, 3, 'A decision can be argued about, which is exactly why the report has to say which side of it a design sits on.'),
  ('esp', 'advanced', 'module', 'm06-the-expert-reading', 2, 'Rounding a stage count up, the rounded gradient constant 0.433 and the linear scaling of a nameplate current are what?', '["Conventions, defensible and not unique, so each has to be stated out loud.", "Artefacts of assembly, so each has to be worked around.", "Decisions, so each of them wants a signature.", "Defects, none of which the review was willing to correct."]'::jsonb, 0, 'The rounded constant sits 0.076982 percent from the exact conversion, and the linear scaling is the published behaviour above half load.'),
  ('esp', 'advanced', 'module', 'm06-the-expert-reading', 3, 'Two fields sharing the name loadFraction, an ampacity flag that cannot fail and a warning that printed its own threshold are examples of what?', '["Conventions, which need only be stated.", "Decisions, which the designer signs.", "Artefacts of how the code was assembled, which have to be worked around until somebody is allowed to fix them.", "Refusals, each being the engine declining to guess."]'::jsonb, 2, 'Only the last of those three was repaired, because a message is the one surface in a shipped engine that nothing downstream consumes.'),
  ('esp', 'advanced', 'module', 'm06-the-expert-reading', 4, 'Why does an error introduced at one step of this chain stay invisible at the next?', '["Every step is linear, so a proportional error is divided away again by the step that follows it and never reaches the surface fields.", "Every step accepts whatever number it is handed.", "Every step carries its own warning, and the warnings are raised on the design as a whole rather than against the field that produced them.", "Every step is computed inside a single function, so no intermediate value is ever available for a reader to check against a second source."]'::jsonb, 1, 'The chain runs head required to shaft horsepower to amps to volts and kVA at surface, and nothing anywhere in it looks back.'),
  ('esp', 'advanced', 'module', 'm06-the-expert-reading', 5, 'What does the tier require of the two brake powers in a finished report?', '["Both recorded, and the one the design is built on named as the power at the head required or at the head made.", "The larger recorded, the published sizing rule having settled which of the two a motor is chosen on.", "The smaller recorded, since every electrical field in this package is built on it and a report should carry what its numbers came from.", "Whichever is larger for the motor and whichever is smaller for the cable."]'::jsonb, 0, 'The gap is 0.037345 percent on golden design gassyOffshore and 2.503380 percent on teaching well IBENO-2, so a short stack is where it bites.'),
  ('esp', 'advanced', 'module', 'm06-the-expert-reading', 6, 'Which comparison confirms that the spread between a stack''s two horsepowers is nothing but the integer rounding?', '["The ratio of the two powers is the ratio of the two stage counts before and after the rounding.", "The gap is one stage of brake power per stage, whatever the stack.", "The gap is the rounding margin divided by the stage efficiency read at the duty rate, which is why it grows as the efficiency falls away from the best point.", "The ratio of the two powers is the ratio of the two heads, to machine precision on every case."]'::jsonb, 3, 'Brake power is linear in head at a fixed rate and efficiency, so the margin is simply the rounding expressed a second time.'),
  ('esp', 'advanced', 'module', 'm06-the-expert-reading', 7, 'Why must each load fraction in a report be labelled with the module it came from?', '["One is measured and one is computed.", "One is utilisation against the usable rating and one is the electrical fraction against the plate, and they agree only at a derate of zero.", "One is a fraction and one is a percentage.", "One belongs to the pump and one to the motor."]'::jsonb, 1, 'On teaching well QUA-IBOE-4 at a 12 percent derate they read 1.0842751471 and 0.9541621294, so they can straddle one and disagree about an overload.'),
  ('esp', 'advanced', 'module', 'm06-the-expert-reading', 8, 'Which rating do the amps come off?', '["The derated rating, since that is what the motor may be asked to deliver.", "The plate, with the thrust derate applied afterwards to the current itself.", "The plate, and the weak estimate flag is checked before the figure is quoted.", "The usable rating, which is the plate multiplied by the derating factor and is therefore the honest denominator for anything the machine has to do."]'::jsonb, 2, 'Below half load the scaling is linear where the machine is not, so a fifth of plate returns 9.8000 A with the estimate flagged.'),
  ('esp', 'advanced', 'module', 'm06-the-expert-reading', 9, 'How should a cable pick be written up?', '["Candidates smallest first with each drop against the limit, the one taken named, and the ampacity half stated in words as not having run.", "As the conductor that carries the current, since the routine tested the drop half and the ampacity half of the published method alike before it returned anything at all.", "As the conductor with the lowest drop, that being the one the scan settles on.", "As a conductor whose safety cannot be judged until an ampacity column arrives."]'::jsonb, 0, 'A published gate takes 192.000000 A down 6 AWG at 3.733233 percent, which is exactly true as a drop result and unsupported as an ampacity one.'),
  ('esp', 'advanced', 'module', 'm06-the-expert-reading', 10, 'What does the checklist require of the four surface fields?', '["All four quoted, with the conductor heat taken off the real power so that a reader can see for himself how much of what left the switchboard reached the motor at the bottom of the string.", "All four quoted, with no balance attempted between them.", "The apparent power and the heat only, those two being what equipment is ordered on.", "All four quoted, with the motor efficiency stated beside them."]'::jsonb, 1, 'Golden electrical case 1 ends at 2481.51704573 V and 143.98680570 kVA, leaving 4.72992077 kW in the copper, and no combination of those is motor input power.'),
  ('esp', 'advanced', 'module', 'm06-the-expert-reading', 11, 'How should a ratio be carried into a surveillance report?', '["As the flag alone, the ratio behind it being an intermediate value of no further use to a reader once the band it fell in has been decided.", "As a whole percentage.", "As a pass or a fail on each band.", "As a number with a decimal on it, before and beside any flag it raised."]'::jsonb, 3, 'A ratio sitting at a threshold raises nothing and still says where the pump is, which is why the flags alone survive being wrong about the cause less well than the numbers do.'),
  ('esp', 'advanced', 'module', 'm06-the-expert-reading', 12, 'Where does this module hand the problem to somebody else?', '["At the stage curve, the drive frequency and the fluid gradient.", "At the plate, the length and the temperature.", "At ampacity, at motor efficiency and at viscosity.", "At the thrust derate, the power factor and the voltage drop limit, all three of which reach the calculation as caller inputs with published defaults behind them."]'::jsonb, 2, 'Each is a refusal to guess rather than a gap: the engine will not invent an ampacity, an efficiency curve or a viscosity correction.'),
  ('esp', 'advanced', 'module', 'm06-the-expert-reading', 13, 'What has to arrive before an ampacity check can decide anything?', '["A manufacturer column against the insulation system and the well temperature, ampacity being an input and not a property of the copper.", "A wider voltage drop limit.", "A conductor temperature computed from the cable loss.", "A second candidate table sorted by outside diameter."]'::jsonb, 0, 'Supplied with such a column the 192 A gate takes 1 AWG instead of 6 AWG, and the conductor heat falls from 51.646421 kW to 16.206821 kW.'),
  ('esp', 'advanced', 'module', 'm06-the-expert-reading', 14, 'What does the electrical half of an ESP design earn?', '["A defensible estimate of what the installation will cost to run, formed from the real power at the surface and the hours the well is expected to produce for.", "A head requirement turned into equipment somebody can buy, and a pair of numbers surveillance can compare against later.", "A motor that will not be reported as overloaded at any thrust derate the selection is later run at, whichever of the two load fractions is read.", "A cable that carries its current safely."]'::jsonb, 1, 'Golden electrical case 1 ends at 2481.51704573 V and 143.98680570 kVA, which is an order rather than an opinion.'),
  ('esp', 'advanced', 'module', 'm06-the-expert-reading', 15, 'What does none of this calculation improve?', '["The head required, which the fluid settles.", "The published stage curve behind it.", "The decision to pump the well at all.", "The surveillance record, which arrives from the field already measured and is only ever read backwards against the curve."]'::jsonb, 2, 'A perfectly sized motor on a well that should not have been pumped is an accurate account of horsepower nobody wanted.'),
  ('esp', 'advanced', 'final', null, 1, 'A team is about to size a short stack and wants to know, ahead of any cable work, whether the open question over which brake power feeds the chain could put a different conductor on the well. Which property of the design tells them the risk is real?', '["The nameplate voltage of the motor, because the drop percentage is taken against it, so a low voltage plate magnifies every horsepower disagreement into the percentage the selection limit reads while a high voltage plate suppresses it entirely, whatever the stage count happens to be.", "The drive frequency, since the affinity mapping scales both powers together.", "A conductor moves only when the winning drop lands between the limit divided by the power ratio and the limit itself, a window as wide as the rounding margin, so a stack of a few dozen stages is exposed where a stack of a couple of hundred is not.", "No property tells them, because the two powers differ by less than a horsepower."]'::jsonb, 2, 'On the published gassyOffshore design the power ratio is 1.000373590543 and the window is thousandths of a point, while the teaching well IBENO-2 runs 1.025676584275 on 33 stages.'),
  ('esp', 'advanced', 'final', null, 2, 'An engineer waves away the choice between the two brake powers on the teaching well IBENO-2 with the remark that 0.76450191 hp is nothing against a 60 hp plate. Where does that reasoning fail?', '["Exposure is not measured in horsepower but against the margin the gap is spent, and on a 3300 ft teaching string that well reads 4.938649 percent against a 5.0 percent limit.", "It fails arithmetically, because the gap between the two brake powers is a fixed percentage of the plate rather than of the head, so a 60 hp plate carries proportionally more of it than a 250 hp plate ever would.", "It fails because a thrust derate is taken off the plate before any comparison is made, so the gap has to be weighed against a usable rating of 0.9000 of the plate and not against the plate itself.", "It does not fail, since the sizing raises no warning on that well."]'::jsonb, 0, 'That stack raises 0 warnings on the sizing that produced both powers, so nothing in the result says the decision was close.'),
  ('esp', 'advanced', 'final', null, 3, 'A vendor curve arrives carrying head points and no efficiency points, and the design is taken through to a cable anyway. What reaches the electrical chain?', '["The fit refuses outright and returns ok false.", "Efficiency falls back to the peak value for that housing.", "The chain runs on hydraulic power instead.", "Head still reads, 27.914286 ft at 2500 bbl/d, while brake power per stage is NaN, so the shaft power and every amp built on it come back NaN rather than as an error."]'::jsonb, 3, 'The fit returns ok true with a warning and the best efficiency rate comes back NaN as well, so the head half of the curve keeps working while the power half is absent.'),
  ('esp', 'advanced', 'final', null, 4, 'Suppose a motor for the published highWaterCut design were sized on 116.39870723 hp, the hydraulic power, in place of 172.55965200 hp. Which part of the calculation notices?', '["The cable selection notices, since the drop percentage it forms would be compared against a limit that the lower current breaches, and the routine would come back with no conductor at all.", "No part of it, because every step after the shaft takes the number it is handed.", "The sizing notices, since a motor loaded by only the hydraulic share of the duty falls under the underloaded threshold of 0.5 and raises motorUnderloaded on the design.", "The diagnosis notices, since the amps over nameplate ratio formed from a surveillance record would drop under 0.40 and raise the low amps flag."]'::jsonb, 1, 'The efficiency at that duty is 0.6745418519, and a motor short by the whole of that term still produces a self consistent set of amps, volts and kVA.'),
  ('esp', 'advanced', 'final', null, 5, 'Two colleagues size the same teaching well IBENO-2 stack, one against a requirement of 700 ft and one against 720 ft. Both land on 32 stages making 721.171425 ft. Why do their electrical numbers not agree?', '["Because the stage count is rounded up in each run and lands on a different integer, so the head the stack makes differs between them and carries that difference into the brake power the amps are built on.", "Because head per stage is read at the duty rate, and a different head requirement moves the duty along the stage curve, which shifts the head per stage, the efficiency and the brake power per stage together.", "The chain is built on brake power at the head required, which is not one number across the two runs, so the same stack carries 3.024489 percent of margin in one and 0.162698 percent in the other.", "They ought to agree, and a disagreement means one run used the wrong plate."]'::jsonb, 2, 'Head made is 721.171425 ft in both runs, so the stack is the same steel and only the requirement it is judged against moved.'),
  ('esp', 'advanced', 'final', null, 6, 'A new engineer offers a patch moving the electrical chain onto brake power at the head the stack makes, on the ground that the published sizing rule takes that one. What does the criterion this wave worked to say about it?', '["The patch touches returned fields that a design, a spreadsheet and a report consume, so it moves numbers somebody is reading today and belongs to an owner rather than to a reviewer.", "The criterion permits it, because PetroWiki is the authority on motor sizing and a package that departs from the published method is carrying an arithmetic defect rather than an open decision that anybody has to sign for.", "The criterion permits it, since the two powers agree to three figures.", "The criterion is silent, because no gate covers the two powers."]'::jsonb, 0, 'One of the five findings examined in that wave was changed, and it touched three message templates, no threshold and no returned field.'),
  ('esp', 'advanced', 'final', null, 7, 'Say the package were rebuilt to take brake power at the head the stack makes. Which surface numbers would come back different?', '["The cable loss alone, since it goes as the square of the current while the drop, the surface voltage and the apparent power are linear in it and absorb a change of that size without moving.", "The drop percentage and the conductor alone, since the surface voltage and the apparent power are formed from the nameplate voltage and are therefore fixed by the plate rather than by the shaft.", "None of them, because the derate does not reach the current.", "Every one of them, because the current moves and the drop, the surface voltage, the apparent power and the cable loss are each built on it."]'::jsonb, 3, 'The chain is linear from the load fraction to the drop, so an understatement of 2.503380 percent on the teaching well IBENO-2 arrives at the drop percentage at full size.'),
  ('esp', 'advanced', 'final', null, 8, 'Sizing on the teaching well QUA-IBOE-4 at a 12 percent derate now reports that the shaft needs 95.4 hp against a 100 hp motor derated 12 percent for thrust, a usable 88.0 hp, 108.4 percent of what it may carry. The older wording printed only the first two of those figures. What did it invite?', '["Reading the derate as already taken off the 95.4 hp figure.", "Reading 95.4 hp against a 100 hp plate as comfortable and closing the warning, since the pair of numbers printed do not overlap and the usable rating the verdict was formed against was missing.", "Recomputing the current against the derated rating.", "Treating the flag as an underload rather than an overload."]'::jsonb, 1, 'The selection fraction behind that sentence is 1.0842751471, and nothing about the shaft or the plate changed when the wording did.'),
  ('esp', 'advanced', 'final', null, 9, 'A supervisor holds a sizing report calling the motor on one well overloaded and an electrical report on the same motor and the same well raising nothing. Which of the two should be corrected?', '["The sizing, because it divides by the derating factor and so measures a load the machine never sees, which is the arithmetic error that produced the disagreement in the first place.", "The electrical report, because it leaves the thrust derate out and therefore understates the loading of the motor by the whole of that derate at every operating point on the well.", "Neither, because the two figures are different quantities under one name and the repair is a label.", "Both, because two functions in one domain returning one field name with two values is an arithmetic defect wherever it appears and each side has to be formed again."]'::jsonb, 2, 'On that well at a 5 percent derate the selection fraction reads 1.0043811889 while the electrical fraction stays at 0.9541621294.'),
  ('esp', 'advanced', 'final', null, 10, 'A design is run again with the thrust derate moved from 0 to 20 percent and the amps come back unchanged. A junior engineer raises it as a defect. What belongs in the log instead?', '["Current follows the work the shaft is doing and not the allowance, so amps that moved with a derate would be the defect and amps standing still are the module behaving.", "The current is held because the module keeps the load fraction from the first run, and the entry should be that a design has to be created again rather than run again before a derate can reach the electrical calculation at all.", "The entry is right, and a derate should reach the amps.", "The amps stood still because the plate was not changed."]'::jsonb, 0, 'PetroWiki gives motor current as nearly linear with horsepower loading, and no meter would read a rise while the mechanical duty stood still.'),
  ('esp', 'advanced', 'final', null, 11, 'A summary sheet prints the electrical load fraction for the published gassyOffshore design beside 110.273867 kW and calls the second figure what the fraction implies at surface. Is that fair?', '["It is fair, because motor input power is the apparent power at surface multiplied by the power factor and then by the load fraction, so the fraction is one of the three terms the figure is built from.", "It is fair so long as the power factor at surface was the same 0.85 the sheet quotes, since the two constants enter one product and are interchangeable within it.", "It is not, because a fraction is a utilisation and not a current.", "It is not, because that figure needs a stated motor efficiency of 0.85, which lives outside the electrical call altogether."]'::jsonb, 3, 'That kW figure is 125.69771587 hp of shaft carried through an assumption held about the motor, and no combination of the returned surface fields equals it.'),
  ('esp', 'advanced', 'final', null, 12, 'A fleet review ranks wells by the loadFraction printed in each design report. What has to be settled before the ranking carries any meaning?', '["That every well was read at one drive frequency, because the affinity laws move head per stage and therefore the stage count, the shaft power and the fraction that follows, so wells at different speeds are not comparable at all.", "That every fraction was divided by the same kind of rating, since a derate on its own moves the teaching well IBENO-2 from 0.4962380648 to 0.5223558577.", "That every well sat above half load when its report was written.", "That the plates were catalogue motors rather than field motors."]'::jsonb, 1, 'Neither of those two figures describes a busier motor, and the field itself never names the rating it divided by.'),
  ('esp', 'advanced', 'final', null, 13, 'A surveillance record on a lightly loaded motor raises the low amps flag at 39.0 percent of nameplate. What standing does that reading carry?', '["It is a measurement, and the flag confirms it.", "It is void, since the band closes below 0.40.", "It is a linear estimate rather than a measurement of the machine, because below about half load the real current flattens toward the magnetising current while the scaling keeps falling.", "It is a gas lock verdict rather than a reading."]'::jsonb, 2, 'At a fifth of plate the engine returns 0.2000 and 9.8000 A with the estimate flagged weak, and hands the number back anyway.'),
  ('esp', 'advanced', 'final', null, 14, 'Two catalogue motors are weighed for one duty and the 150 hp frame at 48 A is preferred to the 100 hp frame at 49 A, partly to keep the cable small. What has that preference overlooked?', '["Amps fall because the plate voltage rises, and that same voltage is the denominator a drop percentage is taken against.", "It overlooks the thrust derate, which cuts the usable rating of the larger frame further than the smaller one and so raises the selection load fraction of the motor that was chosen to be the comfortable one.", "It overlooks the series outside diameter, 5.43 in against 4.56 in, which decides whether the motor passes the casing and is the only difference between the frames a cable calculation can see.", "It overlooks that the current in a conductor is the nameplate current itself and not the nameplate scaled by a load fraction, so the frames draw 48 A and 49 A whatever the shaft is doing."]'::jsonb, 0, 'The 150 hp frame is a 2000 V plate against 1300 V, and the drop, the surface voltage and the apparent power all move with that.'),
  ('esp', 'advanced', 'final', null, 15, 'One well takes 6 AWG at 18.857046 A and the published gate takes 6 AWG at 192.000000 A. What single sentence covers the conductor line in both reports?', '["The conductor is undersized in both, because a table declaring no ampacity cannot certify any candidate and every pick made over it has to be treated as unsupported until a manufacturer column arrives.", "The first pick is safe and the second one is not.", "Both picks are sound, since the ampacity check passed.", "The ampacity half of the published method did not run, so each pick states only that a resistive drop stayed inside the limit."]'::jsonb, 3, 'Calling the 18.857046 A pick unsafe is simply false, and no ampacity table would object to 6 AWG at that current.'),
  ('esp', 'advanced', 'final', null, 16, 'A design for a 250 degF well is run with 2 AWG at its 77 degF catalogue resistance. What has that done to the figures a reviewer sees?', '["It understates the drop and leaves the cable loss alone, because the loss is formed from the current and the length while the drop is the only field carrying a corrected resistance into its result.", "It understates the resistance by a factor of 1.37771667, and the drop, the surface voltage and the cable loss are short by that same multiple.", "It leaves the pick where it was and moves only the reported figures, because selection compares candidates against one another and a resistance error applied to all five cancels out of that comparison.", "It raises a warning against the temperature input."]'::jsonb, 1, 'The correction is linear at 0.0021833333 per degF from a 77 degF reference, and nothing in the returned object says which temperature was assumed.'),
  ('esp', 'advanced', 'final', null, 17, 'After a review a design moves its thrust derate from 0 to 20 percent and its power factor from 0.85 to 0.88, and the electrical package is run again. What comes back different?', '["Everything downstream of the load fraction moves.", "Nothing at all, since neither input enters this package.", "The real power at surface, because the power factor multiplies the apparent power, while the current, the drop, the conductor and the surface voltage all stand still.", "The apparent power and the cable loss only."]'::jsonb, 2, 'The amps, the drop, the pick and the weak estimate flag are built on the underated fraction, so a design changing only its derate produces an identical electrical result.'),
  ('esp', 'advanced', 'final', null, 18, 'A specification asks for the conductor with the most headroom available and the routine hands back 6 AWG at 3.142777 percent while 1/0 AWG sits at 0.781793 percent. Why did the specification not get what it asked for?', '["The scan stops at the first conductor clearing the limit, so what comes back is the smallest acceptable one and headroom is bought by tightening the limit.", "The routine ranks candidates on cost per foot before the drop limit is applied, so a heavier conductor is reached only when the cheaper ones fail, and 1/0 AWG was set aside on price rather than on any electrical ground.", "The scan runs from the largest conductor downward and keeps the last candidate that passed, which on this well is the smallest in the table, so the specification would have to reverse the order of the table to be honoured.", "The routine weighs armour, insulation temperature rating and outside diameter alongside the drop, and on this string those three favoured the smaller conductor even though its drop is the larger of the two."]'::jsonb, 0, 'Cost, armour, outside diameter, insulation rating and weight are absent from the shipped table and from the decision.'),
  ('esp', 'advanced', 'final', null, 19, 'A selection comes back with no conductor at all, so the run is repeated at a 10 percent limit and one appears. What has the second run established?', '["That the first run was in error, because a table of five conductors returning nothing has failed to evaluate its own candidates, and the wider limit is what allows the comparison to be made at all rather than what changes its verdict.", "That the well needs a motor on a higher plate voltage.", "Only that a different acceptance criterion was recorded, since the drop on the conductor it names has not moved.", "That the ampacity check has become the deciding one."]'::jsonb, 2, 'The teaching well QUA-IBOE-4 leaves even 1/0 AWG at 6.017615 percent, and returning nothing is a verdict rather than a crash.'),
  ('esp', 'advanced', 'final', null, 20, 'A motor running at a fifth of its plate draws an estimated 9.8000 A and a conductor is chosen on that figure. What is the standing of the choice?', '["It is sound, because the selection forms the current again from the shaft power and the plate rather than accepting a flagged figure handed to it, so a weak estimate never reaches the drop.", "It is void, because the selection declines to run on a current carrying the weak estimate flag and returns nothing until the load fraction rises above 0.5.", "It is conservative, since a linear scaling understates the real current.", "It inherits an estimate the engine has flagged as weak, and nothing in the selection carries that flag forward."]'::jsonb, 3, 'Below about half load the real current flattens toward the magnetising current while the scaling continues toward zero, so a drop built on it sits on the low side of the truth.'),
  ('esp', 'advanced', 'final', null, 21, 'A house standard takes the drop percentage against the voltage the switchboard presents instead of against the plate. When does that choice change a conductor?', '["Never, because the surface voltage is the plate voltage plus the drop, and two denominators differing by the drop itself cancel when the ratio is formed, which leaves the percentage where it was.", "Only where the conductor runs hotter than 180 degF.", "Whenever the winning candidate sits near the limit, since dividing by the larger voltage always understates the drop and a pick is decided in the last fraction of a percent.", "Only on motors below 1300 V of plate."]'::jsonb, 2, 'Golden electrical case 1 divides 81.51704573 V by 2400 V and not by 2481.51704573 V, and golden electrical case 2 is decided at 4.983392 percent against a 5.0 percent limit.'),
  ('esp', 'advanced', 'final', null, 22, 'A reader holds the drop percentage, the surface voltage, the apparent power and the cable loss for one design and tries to close a power balance out of them. What may fairly be concluded?', '["Nothing about motor input power, which needs an efficiency held outside the call, so the loss can honestly be quoted only as a percentage of the real power.", "That motor input power is the real power at surface less the cable loss, which is the balance the four fields were assembled to support and the reason the loss comes back in the same units as the power it is taken from.", "That the real power and the cable loss added together are what a surface meter reads, since the meter sits above the conductor and therefore sees its heat as well as the load the motor draws.", "That the apparent power already contains the loss."]'::jsonb, 0, 'On golden electrical case 2 the loss is 15.573059 percent of 87.75828739 kW, and a subtraction would be a claim about where the power went.'),
  ('esp', 'advanced', 'final', null, 23, 'A switchboard is ordered on an apparent power worked out from the motor plate voltage rather than from the voltage at the top of the cable. What has been ordered?', '["Equipment sized over the duty by the drop.", "Equipment sized under the duty, because apparent power is formed on the surface voltage, which already carries the whole of the drop.", "The right equipment, since the plate is what the motor sees.", "Equipment right in kVA and wrong in kW."]'::jsonb, 1, 'Golden electrical case 1 forms 143.98680570 kVA on 2481.51704573 V and 33.500000 A.'),
  ('esp', 'advanced', 'final', null, 24, 'The published gate puts 192.000000 A down 6 AWG at a drop of 3.733233 percent, and a review passes the design on that figure. What did the drop check not see?', '["That the string is 1000 ft, short enough that the drop percentage is dominated by a 4160 V plate rather than by the conductor, so the check was answering a question about the motor rather than about the cable.", "That the drop was formed at the 77 degF reference rather than at the temperature of the well, so the true percentage stands above the figure the review was shown by about a third of itself.", "That the limit on that run had been widened from its 5 percent default, so the margin the review read as comfortable was measured against a criterion nobody had signed for the installation.", "That the conductor is turning 51.646421 kW into heat, loss going as the square of the current where the drop goes as the current itself."]'::jsonb, 3, 'Supplying a manufacturer ampacity column moves that pick to 1 AWG and the loss to 16.206821 kW, with no arithmetic changed.'),
  ('esp', 'advanced', 'final', null, 25, 'An assumed conductor temperature is lowered until a marginal drop passes, and every returned field then agrees with every other. Why is that agreement no defence?', '["It is a defence, because the returned watts are what would set the conductor temperature and the engine iterates the two until the assumed value and the dissipation agree, which makes a self consistent result a converged one.", "The drop and the loss are formed on different resistances.", "The temperature is an input nothing checks, so the resistance, the drop and the loss fall together and the result is self consistent in the direction that flatters the design.", "A warning is raised when the temperature falls under 77 degF."]'::jsonb, 2, 'The same 2 AWG conductor reads 0.1593000000 ohms per 1000 ft at 77 degF and 0.2194702650 at 250 degF, and nothing feeds the dissipated watts back.'),
  ('esp', 'advanced', 'final', null, 26, 'A finance team proposes billing well energy off the real power the surface call returns. What is wrong with that?', '["The power factor inside it is one assumed constant and the motor efficiency is absent altogether.", "The figure is an apparent power rather than a real one, so billing from it would charge for the reactive component that a meter at the surface never records as consumption at all.", "The figure covers the conductor alone, because the surface call returns the power a cable dissipates and not the power crossing the switchboard into the installation.", "The figure is quoted at the plate voltage rather than at the surface voltage, so it understates consumption by the whole of the cable drop for every hour the well runs."]'::jsonb, 0, 'The power factor is a caller input, 0.85 on golden electrical case 1 and 0.88 on case 2, and a real motor''s power factor falls away from its plate value at part load.'),
  ('esp', 'advanced', 'final', null, 27, 'A surface voltage of 1506.44804157 V is quoted to a switchboard supplier out of a run whose drop is 15.88061858 percent. What has been passed on?', '["A voltage that cannot be built, because the field comes back only for candidates that passed the drop check and a run at that percentage would have carried no surface voltage in it at all.", "A voltage computed in full precision for a conductor that no selection at the default limit would have accepted.", "A voltage correct but incomplete, because the field holds the resistive drop and the reactive drop separately and only the resistive half was passed to the supplier.", "A figure that judges the conductor rather than reporting it."]'::jsonb, 1, 'That field only reports, and the drop percentage is the field that judges.'),
  ('esp', 'advanced', 'final', null, 28, 'A client asks what a well will consume, having been handed all four surface fields. What has to arrive before that question can be answered?', '["A manufacturer ampacity column for the conductor.", "The thrust derate the sizing was run at.", "A measured power factor at the switchboard.", "A motor efficiency the caller states out loud, since nothing in the call knows one."]'::jsonb, 3, 'On golden design gassyOffshore, 125.69771587 hp at a stated 0.85 gives 110.273867 kW of motor input, held outside the electrical call.'),
  ('esp', 'advanced', 'final', null, 29, 'Under the old format a shift engineer closed a record whose message read 85 percent beside a flag that fires below 0.85. What is the true account of what has changed since?', '["The threshold moved down to the first value that could be printed honestly at whole percent, which is why the band beside it no longer produces a sentence contradicting the flag standing over it.", "The record now returns the ratio as well as the flag.", "Three message templates, with no threshold, no returned field and no arithmetic touched, so every flag still fires at the ratio it always did.", "The band was narrowed until the collision could not arise."]'::jsonb, 2, 'A message is read once by a person and consumed by nobody, which is why it was the one surface in that wave able to be repaired.'),
  ('esp', 'advanced', 'final', null, 30, 'A surveillance run on a stack returns a head ratio of 0.8500 and raises nothing. The site logs the pump as healthy. What should the log have said?', '["That the stack made 4760.000000 ft where its curve expects 5600.000000 ft and no band was crossed, which is a reading rather than a verdict.", "That the pump is sound, because the comparison is made against the curve the stack was built on and a result clearing every band is the strongest statement the function can make about a running machine.", "That the reading is void, because a ratio landing on a threshold cannot be resolved by a strict inequality and the record has to be taken again before anything is entered against the well.", "That the stack is worn, since the ratio sits at the band."]'::jsonb, 0, 'Silence means no band was crossed, and reading it as a clean bill of health is the most expensive mistake available here.'),
  ('esp', 'advanced', 'final', null, 31, 'A diagnosis is handed a specific gravity worked out from a fluid density, while the design it is checked against was built on the field gradient constant. What does that do to the verdict?', '["It leaves the ratio alone, because the same gravity sits in the head the stack is expected to make and in the head recovered from the two pressures, so it divides straight out of the comparison.", "It moves the recovered head and the ratio with it, and the outcome cannot be told apart from a worn stack.", "It raises the high head flag, which is the one message in the set listing the fluid gradient among its candidate causes, so the engine names the error for the reader on the spot.", "It changes the region word, because the duty is measured as a multiple of the best efficiency rate and a gradient enters that multiple through the rate at depth."]'::jsonb, 1, 'The recovery divides by 0.433 times the specific gravity, and that rounded constant stands 0.076982 percent from the exact one.'),
  ('esp', 'advanced', 'final', null, 32, 'A record raises the low head flag and the downthrust flag together, and an analyst writes that the stack is worn and running left of its range. Which half of that survives?', '["Neither half, because the function offers no opinion on which of two flags matters more and a record carrying two of them has to be settled by measurement before either may be written into a report.", "The wear half, because the flag fires on the head ratio.", "Both halves, since two flags agreeing confirm each other.", "The region half, that being a statement about where the duty landed, while wear is one of three causes the low head flag names and declines to choose between."]'::jsonb, 3, 'Wear, free gas through the stages and a wrong stage count each lower the head a stack makes without touching the curve the comparison is against.'),
  ('esp', 'advanced', 'final', null, 33, 'A well is observed running steadily at a head ratio of 0.8400, and an engineer proposes moving the low head band down so it stops raising a warning. May that be done?', '["It may not, because the four bands are constants deciding flags in a live application, and the criterion permits a change only where nothing downstream consumes what it touched.", "It may, since the bands are inputs the caller sets.", "It may, provided the published gate fixture is updated too.", "It may not, but only until the well is measured twice."]'::jsonb, 0, 'A returned field is consumed by a design, a spreadsheet and a report, while a message is read once by a person, and that is the whole of the distinction.'),
  ('esp', 'advanced', 'final', null, 34, 'An operator runs a diagnosis on a well that is shut in, and on a motor whose nameplate current was never entered. What comes back?', '["A refusal on both counts, since the function declines to return a result it cannot form and reports which of the two inputs was missing so that the caller may supply it.", "A head recovered from the two pressures instead, and an amps ratio formed against the nameplate power rather than the nameplate current, so both readings still come back.", "A NaN head with a region of invalid and inside the published range false, and no amps reading at all.", "A zero head and a zero amps ratio, both flagged."]'::jsonb, 2, 'It behaves as motorCurrent does, returning NaN when either the nameplate power or the nameplate current is zero.'),
  ('esp', 'advanced', 'final', null, 35, 'A reviewer points out that a ratio of 0.8499 still prints as 85.0 percent and calls the repair a failure. What is the answer to that?', '["The reviewer is right, and the repair should have printed the ratio to four decimal places so that no value inside either band could ever render as the number the comparison was made against.", "The band that can still print its own threshold is half the width it was, and any fixed precision keeps one.", "The reviewer is right on the head band and wrong on the other two, because the amps bands are formatted differently and neither of them holds a value that prints as its own threshold after the change.", "The printed figure is not the ratio the comparison used, since the message rounds a value the function had already rounded once when it formed the head ratio out of the two heads."]'::jsonb, 1, 'The returned ratio is unrounded, so carrying it beside the flag is what lets a record survive the format it was printed in.'),
  ('esp', 'advanced', 'final', null, 36, 'Which single mistake would make every electrical field on a design wrong at once, and what comparison catches it?', '["Quoting the head a stack makes rather than the head required, caught by dividing one by the other and confirming the quotient is bounded by one stage of the design as it was built.", "Reading conductor resistance at the reference temperature, caught by taking the ratio of the drop to the loss, which is unity only where the resistance used in the two is the same.", "Using hydraulic power for the duty, caught by the region word.", "Taking the utilisation figure out of the sizing as the electrical one, caught by checking that the two agree at a derate of zero."]'::jsonb, 3, 'On the teaching well QUA-IBOE-4 at a 12 percent derate that substitution is worth 13.011302 points, and both reports would stay internally consistent.'),
  ('esp', 'advanced', 'final', null, 37, 'How can a design be correct in every returned field and still describe an unsafe installation?', '["Because a conductor was picked on drop alone, and the fields say nothing about whether the well should have been pumped at all.", "It cannot, because the fields together cover the motor, the conductor and the surface equipment, and an installation whose every computed quantity is right has been checked against every published rule the method carries.", "Because the fields come back to more digits than the inputs carry.", "Because a returned field can be right and reported in the wrong units."]'::jsonb, 0, 'A perfectly sized motor on a well that should not have been pumped is an accurate account of horsepower nobody wanted.'),
  ('esp', 'advanced', 'final', null, 38, 'For each of the two seams in this tier a reviewer has to decide whether a number or a label is at fault. Which way do they fall?', '["Both fall to the label, since neither pair holds a wrong value.", "Both fall to the number, since two values cannot both ship.", "The two brake powers are one quantity computed twice, so at most one may feed the chain and a number is at stake, while the two load fractions are two quantities under one name, so both stand and the name is the defect.", "The load fractions are the open decision and the powers the naming defect."]'::jsonb, 2, 'That is the test to apply anywhere: ask whether two figures are one thing computed twice or two things wearing one label.'),
  ('esp', 'advanced', 'final', null, 39, 'A colleague files the ampacity flag that cannot fail under conventions, alongside rounding stages up and the rounded gradient constant. Where does it belong?', '["With the decisions, because the choice not to ship an ampacity column was made deliberately and somebody signs for it, which is what puts a quantity on that list rather than on either of the other two.", "With the artefacts, a convention being defensible and needing to be stated where an artefact has to be worked around until somebody is allowed to fix it.", "With the conventions, since the column is absent by design.", "Nowhere, because a flag is not a number."]'::jsonb, 1, 'Declining to ship the column is defensible on its own, and leaving a check in place with nothing to check against is what makes a report misleading.'),
  ('esp', 'advanced', 'final', null, 40, 'A well produces a crude whose in situ kinematic viscosity is 21.517241 cSt. What does the engine do, and what has to arrive?', '["It applies a correction off the Hydraulic Institute chart held in the package and returns corrected head, efficiency and rate together with a note recording which factors were used on the reading.", "It declines the reading altogether and returns NaN for head and for efficiency, on the ground that a water curve read on a viscous fluid is a curve read wrongly and no number should come out of it.", "It corrects the efficiency and not the head, because the viscous penalty falls on the power a stage absorbs rather than on the head it makes at a given rate.", "It flags that a correction is required, applies none, and waits for Hydraulic Institute factors from the caller."]'::jsonb, 3, 'The threshold is 10 cSt, and applying invented factors would be worse than applying none, so the stage counts stand unusable until factors are supplied.'),
  ('esp', 'advanced', 'final', null, 41, 'Two engineers hand in electrical results for one well that differ in the fourth figure, and each set is internally consistent. What is compared first?', '["Which of the two brake powers each chain started from, since that difference reaches the drop percentage at full size.", "The conductor temperature each of them assumed, since the copper correction is the only step in the chain able to move a result while leaving every other returned field in agreement with it.", "The power factor each of them used, because it multiplies the apparent power and carries into the real power, the cable loss percentage and the drop a conductor was chosen on.", "The nameplate each of them read the plate current from."]'::jsonb, 0, 'A report naming neither of the two powers cannot be checked, which is why both belong on the page.'),
  ('esp', 'advanced', 'final', null, 42, 'A record archived three years ago kept the flags a diagnosis raised and none of the numbers behind them. What was lost?', '["Nothing, since flags carry their thresholds with them.", "The head ratio, the region and the amps ratio, which outlive any verdict attached to them and can be judged again against a threshold later.", "The message text alone, which is formed again on demand.", "The stage curve the comparison was made against."]'::jsonb, 1, 'Carried with a record those numbers survive being wrong about the cause, where a flag alone does not.');
